/* AXIS 토큰: 기본 CSS 변수(--axis-*)와 shadcn 호환 변수(--background · --primary 등). @import 는 @tailwind 보다 앞에 둡니다 */
@import "@axis-ds/tokens/css";
@import "@axis-ds/tokens/css/shadcn";
/* ontology 브랜드: 아래 줄의 주석을 풀고 app/layout.tsx 의 <html> 에 data-brand="ontology" 를 넣습니다 */
/* @import "@axis-ds/tokens/css/brands/ontology"; */

@tailwind base;
@tailwind components;
@tailwind utilities;

/*
 * 테두리 기본색: Tailwind 3 preflight 의 `* { border-color: gray-200 }` 가 shadcn 호환 CSS 의 `* { border-color }` 보다
 * 뒤에 와서 이기므로, `border` 클래스가 다크 · 브랜드에서도 회색으로 남지 않게 AXIS --border 로 되돌립니다
 */
@layer base {
  * {
    @apply border-border;
  }
}

import type { Metadata } from 'next'
// AXIS 대표 글꼴 Pretendard(동적 서브셋). 글꼴 스택은 AXIS preset 이 <html> 에 적용합니다
import 'pretendard/dist/web/variable/pretendardvariable-dynamic-subset.css'
import './globals.css'

export const metadata: Metadata = {
  title: 'AXIS Theme Only',
  description: 'AXIS 토큰 기반 테마 시스템 스타터',
}

// ontology 브랜드를 켜려면 globals.css 의 브랜드 import 주석을 풀고 <html> 에 data-brand="ontology" 를 넣습니다
export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="ko" suppressHydrationWarning>
      <body>{children}</body>
    </html>
  )
}

'use client'

import { useEffect, useState } from 'react'

export function ThemeToggle() {
  const [dark, setDark] = useState(false)

  useEffect(() => {
    const isDark = document.documentElement.classList.contains('dark')
    setDark(isDark)
  }, [])

  function toggle() {
    const next = !dark
    setDark(next)
    document.documentElement.classList.toggle('dark', next)
  }

  return (
    <button
      onClick={toggle}
      className="inline-flex items-center gap-2 rounded-md border px-4 py-2 text-sm font-medium transition-colors hover:bg-accent hover:text-accent-foreground"
    >
      {dark ? '🌙' : '☀️'} {dark ? '다크 모드' : '라이트 모드'}
    </button>
  )
}

/** Tailwind 3 를 PostCSS 플러그인으로 돌립니다(없으면 @tailwind 지시문이 그대로 남아 유틸리티가 생성되지 않음, WI-0037) */
export default {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  },
}

import type { Config } from 'tailwindcss'
import axisPreset from '@axis-ds/tokens/tailwind'

/** 색 · 둥글기 · 글꼴(Pretendard 스택) · darkMode 는 AXIS preset 이 정합니다 */
const config: Config = {
  presets: [axisPreset],
  content: ['./app/**/*.{ts,tsx}', './components/**/*.{ts,tsx}'],
  plugins: [],
}

export default config
